            make_q("What is Exclusive Feature Bundling (EFB) in LightGBM?", ["Selling features to third parties", "Bundling mutually exclusive sparse features (features that rarely take non-zero values simultaneously, e.g. one-hot columns) into single dense features", "A method for encrypting columns", "A technique to sort trees"], 1, "EFB merges sparse, mutually exclusive feature sets to reduce the total number of features evaluated without loss of accuracy."),
