            make_q("What is TreeSHAP?", ["An algorithm that prunes trees", "An optimized algorithm that computes exact SHAP values for tree ensembles in polynomial time $O(T L D^2)$ instead of exponential time", "A visualization tool for leaves", "A decision tree written in Python"], 1, "TreeSHAP exploits tree structure to compute exact Shapley feature attributions in seconds rather than exponential time."),
            make_q("Can Gradient Boosted Trees handle non-linear interactions between features?", ["No, boosting is strictly linear", "Yes, deep decision trees naturally capture high-order non-linear feature interactions without explicit manual interaction terms", "Only if features are multiplied in pandas first", "Only with RBF kernels"], 1, "Every split nested beneath another split models a non-linear interaction ($x_1 > t_1 \\text{ AND } x_2 \\le t_2$).")
